// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title CalldataHelper
 * @notice Remix utility — encodes initialize() calldata for use when deploying
 *         ERC1967Proxy. Deploy this contract, call the relevant function,
 *         copy the `bytes` output, then paste it into the ERC1967Proxy
 *         constructor `_data` field.
 *
 * DELETE or exclude this file before production deployment.
 */
contract CalldataHelper {
    // ── YieldDistributor ─────────────────────────────────────────────────────
    /**
     * @param admin          Your Remix account address
     * @param initialRateWAD 10% APY = 100000000000000000 (0.1e18)
     */
    function encodeYieldDistributorInit(address admin, uint256 initialRateWAD)
        external
        pure
        returns (bytes memory)
    {
        return abi.encodeWithSignature(
            "initialize(address,uint256)",
            admin,
            initialRateWAD
        );
    }

    // ── StakingVault ──────────────────────────────────────────────────────────
    /**
     * @param admin               Your Remix account address
     * @param dktTokenAddr        DiktiToken deployed address
     * @param yieldDistributorAddr YieldDistributor PROXY address
     * @param initialLockPeriod   0 for Remix testing (no lock)
     */
    function encodeStakingVaultInit(
        address admin,
        address dktTokenAddr,
        address yieldDistributorAddr,
        uint256 initialLockPeriod
    ) external pure returns (bytes memory) {
        return abi.encodeWithSignature(
            "initialize(address,address,address,uint256)",
            admin,
            dktTokenAddr,
            yieldDistributorAddr,
            initialLockPeriod
        );
    }

    // ── Convenience: pre-filled for common Remix test values ─────────────────
    /**
     * @notice Quick encode for YieldDistributor with 10% APY.
     *         Replace `admin` with your actual address.
     */
    function encodeYieldDistributorInit10pct(address admin)
        external
        pure
        returns (bytes memory)
    {
        return abi.encodeWithSignature(
            "initialize(address,uint256)",
            admin,
            100000000000000000  // 0.1e18 = 10% APY
        );
    }

    /**
     * @notice Quick encode for StakingVault with no lock period.
     */
    function encodeStakingVaultInitNoLock(
        address admin,
        address dktTokenAddr,
        address yieldDistributorProxyAddr
    ) external pure returns (bytes memory) {
        return abi.encodeWithSignature(
            "initialize(address,address,address,uint256)",
            admin,
            dktTokenAddr,
            yieldDistributorProxyAddr,
            0   // no lock period for testing
        );
    }
}

src/interfaces/IYieldDistributor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title IYieldDistributor
 * @notice Interface consumed by StakingVault to notify the distributor of
 *         stake/unstake events and by users to claim yield with a split.
 *
 * Yield-split mechanic:
 *   When a user stakes, they specify:
 *     - targetProject: the ResearchProject address to receive the donated share
 *     - donateBps:     basis points (0–10_000) of yield to route to that project
 *                      e.g. 7000 = 70% to project, 30% to staker wallet
 *   Both values are locked until the user fully unstakes.
 *   claimYield() auto-splits according to the stored ratio.
 */
interface IYieldDistributor {
    // ─── Structs ──────────────────────────────────────────────────────────────
    struct EpochInfo {
        uint256 totalYield;     // Total simulated yield generated this epoch
        uint256 totalStaked;    // Total DKT staked at epoch snapshot
        uint256 yieldRateWAD;   // Yield rate used (WAD = 1e18 = 100%)
        uint256 blockNumber;    // Block when epoch was recorded
        uint256 timestamp;      // Timestamp when epoch was recorded
    }

    /// @notice Per-user yield-split configuration, set at stake time and locked.
    struct YieldSplit {
        address targetProject; // ResearchProject to receive donated yield share
        uint16  donateBps;     // Basis points donated to project (0–10_000)
    }

    // ─── Errors ───────────────────────────────────────────────────────────────
    error NotStakingVault();
    error EpochTooEarly(uint256 nextAllowed, uint256 current);
    error NothingToClaim();
    error ZeroAddress();
    error ZeroAmount();
    error RateExceedsMax(uint256 rate, uint256 max);
    error InsufficientYieldPool(uint256 requested, uint256 available);
    error InvalidBps(uint16 bps);
    error ProjectRequired();

    // ─── Events ───────────────────────────────────────────────────────────────
    event RewardIndexUpdated(uint256 newIndex, uint256 timestamp);
    event EpochAdvanced(
        uint256 indexed epoch,
        uint256 totalYield,
        uint256 totalStaked,
        uint256 yieldRateWAD,
        uint256 blockNumber
    );
    event YieldClaimed(
        address indexed user,
        uint256 totalClaimed,
        uint256 toStaker,
        uint256 toProject,
        address indexed targetProject,
        uint256 epoch,
        uint256 blockNumber
    );
    event YieldPoolFunded(address indexed funder, uint256 amount);
    event YieldRateUpdated(uint256 oldRate, uint256 newRate);
    event StakingVaultSet(address indexed vault);
    event FundingPoolSet(address indexed fundingPool);

    // ─── Mutating ─────────────────────────────────────────────────────────────

    /**
     * @notice Called by StakingVault when a user stakes DKT.
     * @param user          The staker address
     * @param amount        DKT amount staked
     * @param targetProject ResearchProject address to receive donated yield (address(0) = no donation)
     * @param donateBps     Basis points of yield to route to project (0 = all to staker)
     */
    function notifyStake(address user, uint256 amount, address targetProject, uint16 donateBps) external;

    function notifyUnstake(address user, uint256 amount) external;
    function claimYield() external returns (uint256 claimed);
    function fundYieldPool(uint256 amount) external;

    // ─── Admin ────────────────────────────────────────────────────────────────
    function advanceEpoch() external;
    function setYieldRate(uint256 newRateWAD) external;
    function setStakingVault(address vault) external;
    function setFundingPool(address fundingPool) external;
    function withdrawUnclaimedYield(address to, uint256 amount) external;

    // ─── Views ────────────────────────────────────────────────────────────────
    function pendingYield(address user) external view returns (uint256);
    function yieldSplit(address user) external view returns (YieldSplit memory);
    function currentEpoch() external view returns (uint256);
    function rewardIndex() external view returns (uint256);
    function totalStaked() external view returns (uint256);
    function yieldPool() external view returns (uint256);
    function epochInfo(uint256 epoch) external view returns (EpochInfo memory);
}

src/ProjectFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/proxy/beacon/BeaconProxy.sol";
import "@openzeppelin/contracts/proxy/beacon/UpgradeableBeacon.sol";
import "./ResearchProject.sol";
import "./FundingPool.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title ProjectFactory
 * @notice Deploys new ResearchProject instances as BeaconProxy contracts.
 *         Maintains a registry of all deployed projects for on-chain enumeration
 *         and off-chain indexing.
 *
 * @dev COMPLEXITY LEVEL 4 — contract creation (highest gas cost category).
 *      Immutable — the factory itself is not upgradeable. The ResearchProject
 *      implementation is upgradeable via the UpgradeableBeacon it holds.
 *
 *      Beacon Proxy pattern:
 *        - One UpgradeableBeacon holds the ResearchProject implementation address
 *        - Each project is a cheap BeaconProxy that delegates to the beacon
 *        - Upgrading the beacon implementation upgrades ALL projects simultaneously
 *        - Beacon upgrade is restricted to DEFAULT_ADMIN_ROLE
 *
 *      Gas profile targets:
 *        createProject()  ~300,000-400,000 gas  (BeaconProxy deployment + initialize)
 *        upgradeBeacon()  ~30,000 gas            (single SSTORE on beacon)
 */
contract ProjectFactory is AccessControl {
    // ─── Roles ────────────────────────────────────────────────────────────────
    bytes32 public constant FACTORY_ADMIN_ROLE = keccak256("FACTORY_ADMIN_ROLE");

    // ─── Errors ───────────────────────────────────────────────────────────────
    error ZeroAddress();
    error EmptyTitle();
    error DurationTooShort(uint256 provided, uint256 minimum);
    error DurationTooLong(uint256 provided, uint256 maximum);

    // ─── Constants ────────────────────────────────────────────────────────────
    uint256 public constant MIN_DURATION = 1 hours;
    uint256 public constant MAX_DURATION = 365 days;

    // ─── Events ───────────────────────────────────────────────────────────────
    event ProjectCreated(
        address indexed projectAddress,
        address indexed researcher,
        bytes32 indexed projectId,
        string title,
        uint256 goalAmount,
        uint256 deadline,
        uint256 blockNumber
    );
    event BeaconUpgraded(address indexed oldImpl, address indexed newImpl);

    // ─── State ────────────────────────────────────────────────────────────────
    /// @notice The beacon holding the ResearchProject implementation
    UpgradeableBeacon public immutable beacon;

    /// @notice The FundingPool that all projects route funds to
    FundingPool public immutable fundingPool;

    /// @notice The DKT token used for donations
    IERC20 public immutable dkt;

    /// @notice Ordered list of all deployed project addresses
    address[] public allProjects;

    /// @notice Lookup: researcher address → their project addresses
    mapping(address => address[]) public projectsByResearcher;

    // ─── Constructor ──────────────────────────────────────────────────────────
    /**
     * @param admin                 Admin address (DEFAULT_ADMIN_ROLE + FACTORY_ADMIN_ROLE)
     * @param researchProjectImpl   Initial ResearchProject implementation address
     * @param _fundingPool          FundingPool contract address (immutable reference)
     */
    constructor(
        address admin,
        address researchProjectImpl,
        address payable _fundingPool,
        address _dkt
    ) {
        if (admin == address(0)) revert ZeroAddress();
        if (researchProjectImpl == address(0)) revert ZeroAddress();
        if (_fundingPool == address(0)) revert ZeroAddress();
        if (_dkt == address(0)) revert ZeroAddress();

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(FACTORY_ADMIN_ROLE, admin);

        beacon = new UpgradeableBeacon(researchProjectImpl, address(this));
        fundingPool = FundingPool(payable(_fundingPool));
        dkt = IERC20(_dkt);
    }

    // ─── Core: Create project ─────────────────────────────────────────────────
    /**
     * @notice Deploy a new ResearchProject as a BeaconProxy.
     * @dev    Any address can create a project (permissionless).
     *         The caller becomes the `researcher` of the deployed project.
     *
     * @param  title               Project title
     * @param  milestoneTitles     Array of milestone titles
     * @param  milestoneGoals      Array of milestone DKT goals (informational)
     * @param  milestoneDurations  Array of milestone durations in seconds
     * @return projectAddr         Address of the deployed ResearchProject proxy
     */
    function createProject(
        string calldata title,
        string[] calldata milestoneTitles,
        uint256[] calldata milestoneGoals,
        uint256[] calldata milestoneDurations
    ) external returns (address projectAddr) {
        if (bytes(title).length == 0) revert EmptyTitle();
        require(milestoneTitles.length > 0, "Need at least one milestone");
        require(
            milestoneTitles.length == milestoneGoals.length &&
            milestoneGoals.length == milestoneDurations.length,
            "Milestone array length mismatch"
        );
        for (uint256 i = 0; i < milestoneDurations.length; i++) {
            if (milestoneDurations[i] < MIN_DURATION) revert DurationTooShort(milestoneDurations[i], MIN_DURATION);
            if (milestoneDurations[i] > MAX_DURATION) revert DurationTooLong(milestoneDurations[i], MAX_DURATION);
        }

        bytes memory initData = abi.encodeCall(
            ResearchProject.initialize,
            (
                msg.sender,
                address(fundingPool),
                address(dkt),
                title,
                milestoneTitles,
                milestoneGoals,
                milestoneDurations
            )
        );

        BeaconProxy proxy = new BeaconProxy(address(beacon), initData);
        projectAddr = address(proxy);

        allProjects.push(projectAddr);
        projectsByResearcher[msg.sender].push(projectAddr);

        bytes32 pid = ResearchProject(payable(projectAddr)).projectId();

        fundingPool.grantRole(fundingPool.DEPOSITOR_ROLE(), projectAddr);

        emit ProjectCreated(
            projectAddr,
            msg.sender,
            pid,
            title,
            0,
            0,
            block.number
        );
    }

    // ─── Admin: Upgrade beacon ────────────────────────────────────────────────
    /**
     * @notice Upgrade the ResearchProject implementation for ALL projects.
     * @dev    Only DEFAULT_ADMIN_ROLE. This is a powerful operation —
     *         it upgrades every deployed project simultaneously.
     *         Used in research to compare gas costs across implementation versions.
     */
    function upgradeBeacon(address newImplementation) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (newImplementation == address(0)) revert ZeroAddress();
        address old = beacon.implementation();
        beacon.upgradeTo(newImplementation);
        emit BeaconUpgraded(old, newImplementation);
    }

    // ─── View ─────────────────────────────────────────────────────────────────
    function totalProjects() external view returns (uint256) {
        return allProjects.length;
    }

    function projectsOf(address researcher) external view returns (address[] memory) {
        return projectsByResearcher[researcher];
    }

    function projectsOfCount(address researcher) external view returns (uint256) {
        return projectsByResearcher[researcher].length;
    }

    /// @notice Returns a page of projects (pagination for frontend)
    function getProjects(uint256 offset, uint256 limit)
        external
        view
        returns (address[] memory page)
    {
        uint256 total = allProjects.length;
        if (offset >= total) return new address[](0);

        uint256 end = offset + limit;
        if (end > total) end = total;

        page = new address[](end - offset);
        for (uint256 i = offset; i < end; ) {
            page[i - offset] = allProjects[i];
            unchecked { ++i; }
        }
    }

    function currentImplementation() external view returns (address) {
        return beacon.implementation();
    }
}

